    <section id="exec-tinker" class="w-full py-24 sm:py-32 max-w-7xl">
        <div class="w-full py-24 shadow-xl bg-ink-800 ring-1 ring-inset ring-ink-700 max-w-7xl sm:py-32 rounded-2xl">
            <div class="px-6 mx-auto lg:px-8">
                <div class="max-w-2xl mx-auto lg:text-center">
                    <h2 class="text-base font-semibold leading-7 text-orange-500">Helping you write code fast</h2>
                    <p class="mt-2 text-3xl font-bold tracking-tight text-white sm:text-4xl">Superpowers for running PHP</p>
                    <p class="mt-6 text-lg leading-8 text-ink-300">cpx gives you multiple ways to run PHP code quickly, perfect for running scratch files or quickly running code in your project.</p>
                </div>

                <ul role="list" class="max-w-xl mx-auto mt-16 space-y-8 text-ink-300">
                    <li class="flex items-center gap-x-3">
                        <svg class="flex-none mt-1 text-orange-500 size-6" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor">
                            <path fill-rule="evenodd" d="M2.25 6a3 3 0 0 1 3-3h13.5a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3H5.25a3 3 0 0 1-3-3V6Zm3.97.97a.75.75 0 0 1 1.06 0l2.25 2.25a.75.75 0 0 1 0 1.06l-2.25 2.25a.75.75 0 0 1-1.06-1.06l1.72-1.72-1.72-1.72a.75.75 0 0 1 0-1.06Zm4.28 4.28a.75.75 0 0 0 0 1.5h3a.75.75 0 0 0 0-1.5h-3Z" clip-rule="evenodd" />
                        </svg>
                        <span><x-code class="font-semibold text-white">cpx exec &lt;file.php&gt;</x-code> will run a plain PHP file.</span>
                    </li>
                    <li class="flex items-center gap-x-3">
                        <svg class="flex-none mt-1 text-orange-500 size-6" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor">
                            <path fill-rule="evenodd" d="M2.25 6a3 3 0 0 1 3-3h13.5a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3H5.25a3 3 0 0 1-3-3V6Zm3.97.97a.75.75 0 0 1 1.06 0l2.25 2.25a.75.75 0 0 1 0 1.06l-2.25 2.25a.75.75 0 0 1-1.06-1.06l1.72-1.72-1.72-1.72a.75.75 0 0 1 0-1.06Zm4.28 4.28a.75.75 0 0 0 0 1.5h3a.75.75 0 0 0 0-1.5h-3Z" clip-rule="evenodd" />
                        </svg>
                        <span><x-code class="font-semibold text-white">cpx exec -r &lt;raw php code&gt;</x-code> will execute the given PHP code.</span>
                    </li>
